# Block and tackle + assay math (public-domain formulas)
def tackle_ma(ropes, sheave_eff=0.96):
    # ideal MA = ropes; real accounts sheave friction
    return sum(sheave_eff ** i for i in range(ropes))

for ropes in (2, 3, 4, 6):
    print(f"{ropes}-part tackle: ideal {ropes}:1, real ~{tackle_ma(ropes):.2f}:1")

# Fire assay: gold button weight from sample
def assay_oz_per_ton(button_g, sample_g=29.1667):  # 1 assay ton
    return button_g / sample_g * 29.1667  # ozt per short ton approx
print(f"\n0.5g gold button from 1 assay-ton sample: {assay_oz_per_ton(0.5):.2f} oz/ton")
